namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = new();
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 uppercase alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantity, and space." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Literature, writing, and critical analysis." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and fundamental forces." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Exploration of past events and civilizations." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Specializes in algorithms and programming languages with 20 years of teaching experience.", Email = "lovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Expert in computational theory and artificial intelligence.", Email = "turing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Renowned researcher in abstract algebra and theoretical physics.", Email = "noether@university.edu" },
            new() { Id = 4, Name = "Dr. William Shakespeare", Title = "Distinguished Professor", Bio = "Award-winning author and literary critic with expertise in Renaissance literature.", Email = "shakespeare@university.edu" },
            new() { Id = 5, Name = "Dr. Marie Curie", Title = "Professor", Bio = "Pioneering researcher in nuclear physics and radiation studies.", Email = "curie@university.edu" },
            new() { Id = 6, Name = "Dr. Herodotus", Title = "Associate Professor", Bio = "Specialist in ancient civilizations and historiography.", Email = "herodotus@university.edu" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, Instructor = _instructors[1], Department = _departments[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 301", Title = "Operating Systems", Description = "Principles of operating system design including process management, memory management, file systems, and concurrency.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, Instructor = _instructors[1], Department = _departments[0] },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, Instructor = _instructors[2], Department = _departments[1], IsFeatured = true },
            new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, Instructor = _instructors[2], Department = _departments[1] },
            new() { Id = 6, Code = "ENG 101", Title = "English Composition", Description = "Develop effective writing skills through essays, research papers, and critical analysis of texts.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2] },
            new() { Id = 7, Code = "ENG 205", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and time periods.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2], IsFeatured = true },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 9, Code = "PHYS 202", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory to the Renaissance.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = 5, Instructor = _instructors[5], Department = _departments[4] },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

