+            new() { Id = 7, Code = "ENG 205", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and time periods.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2], IsFeatured = true },
+            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
+            new() { Id = 9, Code = "PHYS 202", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
+            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory to the Renaissance.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = 5, Instructor = _instructors[5], Department = _departments[4] },
+        ];
+    }
+
+    public List<Department> GetDepartments() => _departments;
+
+    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);
+
+    public List<Course> GetCourses() => _courses;
+
+    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
+    {
+        var query = _courses.AsEnumerable();
+
+        if (departmentId.HasValue && departmentId.Value > 0)
+            query = query.Where(c => c.DepartmentId == departmentId.Value);
+
+        if (!string.IsNullOrWhiteSpace(searchTerm))
+        {
+            var term = searchTerm.Trim().ToLowerInvariant();
+            query = query.Where(c =>
+                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
+        }
+
+        return query.ToList();
